style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
/* Base colors */
    :root {
        --bg-main: #f5f1e6;   /* light beige */
        --bg-alt:  #e9e1d1;   /* warm beige */
        --accent:  #a47551;   /* warm medium brown */
        --text-main: #3b2f2f; /* deep coffee brown */
        --text-muted: #6e5c4c;/* softer brown */
        --border: #d6c8b2;    /* subtle border beige */
    }

    /* Body background + text */
    body, html {
        background-color: var(--bg-main) !important;
        color: var(--text-main) !important;
        font-family: "Inter", "Segoe UI", sans-serif !important;
    }

    /* Links */
    a {
        color: var(--accent) !important;
        text-decoration: none !important;
    }
    a:hover {
        text-decoration: underline !important;
    }

    /* Inputs, textareas */
    input, textarea, select {
        background-color: var(--bg-alt) !important;
        color: var(--text-main) !important;
        border: 1px solid var(--border) !important;
        border-radius: 6px !important;
        padding: 6px !important;
    }

    /* Buttons */
    button, [role="button"] {
        background-color: var(--accent) !important;
        color: #fff !important;
        border: none !important;
        border-radius: 8px !important;
        padding: 6px 12px !important;
        cursor: pointer !important;
    }
    button:hover, [role="button"]:hover {
        background-color: #8a5e3b !important; /* darker brown */
    }

    /* Cards / Containers */
    div, section, article {
        background-color: var(--bg-main) !important;
        border-radius: 12px !important;
    }

    /* Remove harsh shadows */
    * {
        box-shadow: none !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
        height: 10px;
    }
    ::-webkit-scrollbar-track {
        background: var(--bg-alt);
    }
    ::-webkit-scrollbar-thumb {
        background: var(--accent);
        border-radius: 6px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #8a5e3b;
    }
}
